@interface RenderPeerFact : NSObject
@property(nonatomic) BOOL selected;
@property(nonatomic) NSUInteger selectedReads,wires;
@property(nonatomic,strong) NSString *lastIdentity;
@end
@implementation RenderPeerFact
- (BOOL)inlineBlockID:(NSString *)identity isSelectedForItem:(OCRTextItem *)item{self.selectedReads++;return self.selected;}
- (void)wireInlineLongCardPanel:(NSPanel *)p item:(OCRTextItem *)item translation:(NSString *)t frame:(NSRect)f stableBlockID:(NSString *)identity{self.wires++;self.lastIdentity=identity;}
@end
@interface RenderHostProbe : FYInlineOverlayController
@property(nonatomic,strong) FYInlineLayoutEngine *engine;
@property(nonatomic,strong) CardContentFact *replacement;
@property(nonatomic) NSUInteger rebuilds;
@end
@implementation RenderHostProbe
- (FYInlineLayoutEngine *)inlineLayoutEngine{return self.engine;}
- (NSColor *)inlinePanelTextColor{return [NSColor colorWithSRGBRed:.2 green:.3 blue:.4 alpha:.6];}
- (NSColor *)inlinePanelFillColor{return [NSColor colorWithSRGBRed:.8 green:.7 blue:.6 alpha:.58];}
- (NSColor *)inlinePanelBorderColor{return NSColor.brownColor;}
- (NSColor *)inlinePanelTitleColor{return NSColor.brownColor;}
- (NSView *)inlineLongCardContentForTranslation:(NSString *)t size:(NSSize)s selected:(BOOL)selected compact:(BOOL)compact placement:(FYInlinePlacement *)p{self.rebuilds++;return (NSView *)self.replacement;}
@end
